def bs_from_ad(d: date) -> tuple[int, int, int]:
    """(year, month, day) in BS for an AD calendar date."""
    days = (d - BS_EPOCH_AD).days
    if days < 0:
        raise ValueError(f'{d} is before BS {BS_FIRST_YEAR}')
    for y in range(BS_FIRST_YEAR, BS_LAST_YEAR + 1):
        for m, n in enumerate(BS_MONTH_LENGTHS[y], start=1):
            if days < n:
                return y, m, days + 1
            days -= n
    raise ValueError(f'{d} is after BS {BS_LAST_YEAR}')


def ad_from_bs(y: int, m: int, d: int) -> date:
    days = d - 1 + sum(sum(BS_MONTH_LENGTHS[yy]) for yy in range(BS_FIRST_YEAR, y)) + sum(BS_MONTH_LENGTHS[y][:m - 1])
    return BS_EPOCH_AD + timedelta(days=days)
